            raise ValueError(
                f"cannot subtract {other.currency} from {self.currency}"
            )
        if other.cents > self.cents:
            raise ValueError("result would be negative")
        return Money(self.cents - other.cents, self.currency)

    def __mul__(self, factor):
        return Money(self.cents * factor, self.currency)

    __rmul__ = __mul__

    def split(self, parts):
        """Split into `parts` shares, giving leftover cents to the first shares."""
        if parts <= 0:
            raise ValueError("parts must be positive")
        base, remainder = divmod(self.cents, parts)
        shares = []
        for i in range(parts):
